from pathlib import Path
p=Path('/mnt/data/aluminate-v1')
def write(name,title,body):
 s=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0a1017"><meta name="description" content="Aluminate premium digital beverage can printing, dimensional finishes, durable decoration and creative freedom."><title>{title} | Aluminate</title><link rel="stylesheet" href="style.css"></head><body data-page="{name}"><div id="header"></div><main>{body}</main><div id="footer"></div><script src="site.js"></script></body></html>'''
 (p/(('index' if name=='home' else name)+'.html')).write_text(s)
cta='''<section class="banner"><span class="eyebrow">YOUR NEXT CAN STARTS HERE</span><h2>Make something<br>extraordinary.</h2><p>Bring us your boldest idea. We'll help turn it into packaging that performs.</p><div class="actions" style="justify-content:center"><a class="btn" href="contact.html">REQUEST SAMPLES / QUOTE ↗</a><a class="btn secondary" href="masterworks.html">EXPLORE THE GALLERY</a></div></section>'''
write('home','Creative Mastery. Engineered.', '''<section class="hero"><div><span class="eyebrow">BEVERAGE CAN PRINTING, REIMAGINED</span><h1>Creative<br>mastery.<br><em>Engineered.</em></h1><p>Extraordinary color. Elevated surface effects. Durability you can count on. Premium digitally printed cans for brands that refuse to look ordinary.</p><div class="actions"><a class="btn" href="contact.html">REQUEST SAMPLES ↗</a><a class="btn secondary" href="capabilities.html">EXPLORE CAPABILITIES</a></div></div><img src="hero.jpg" alt="Conceptual lineup of artistically printed aluminum beverage cans"></section>
<section class="section light"><div class="grid2"><div><span class="eyebrow" style="color:#35729a">CUSTOM CANS. LIMITLESS POSSIBILITIES.</span><h2>Your vision deserves a better canvas.</h2><p>From bold and expressive to refined and minimal, your artwork deserves a printing process as ambitious as your brand.</p><a class="link" href="masterworks.html">DISCOVER MASTERWORKS ↗</a></div><img class="photo" src="gallery.jpg" alt="Conceptual collection of colorful beverage can designs"></div></section>
<section class="section"><div class="wide"><span class="eyebrow">MORE THAN INK ON ALUMINUM</span><h2>A higher standard<br>for what a can can do.</h2><div class="grid4"><div class="tile"><span class="number">01 / COLOR</span><b>Expanded gamut</b><p>Creative color capabilities across complementary digital printing platforms.</p></div><div class="tile"><span class="number">02 / FINISH</span><b>Dual varnish</b><p>Dedicated matte and gloss applications create intentional contrast on one can.</p></div><div class="tile"><span class="number">03 / PROTECTION</span><b>PlasmaMax™ adhesion</b><p>Our adhesion story is built around lasting decoration and practical performance.</p></div><div class="tile"><span class="number">04 / IMPACT</span><b>Elevated effects</b><p>Dimensional and tactile details that make artwork memorable.</p></div></div><div class="actions"><a class="btn" href="capabilities.html">EXPLORE CAPABILITIES ↗</a></div></div></section>
<section class="section light"><div class="grid2"><img class="photo" src="detail.jpg" alt="Conceptual close-up of printed can surface details"><div><span class="eyebrow" style="color:#35729a">FEEL THE DIFFERENCE</span><h2>Surface is part of the story.</h2><p>Imagine low-sheen matte alongside brilliant spot gloss, precisely applied to guide the eye and add another layer to your brand expression.</p><a class="link" href="finishes.html">DISCOVER SURFACE EFFECTS ↗</a></div></div></section>
<section class="section"><span class="eyebrow">THE PRODUCTION ADVANTAGE</span><h2>Technology in service<br>of imagination.</h2><div class="grid2"><div class="tile"><span class="number">HINTERKOPF D360.4</span><h3>Precision and exceptional detail.</h3><p>CMYK + Orange, with dedicated matte and gloss varnish stations. Built for high-definition decoration and creative surface contrast.</p></div><div class="tile"><span class="number">VELOX</span><h3>Expanded creative color options.</h3><p>CMYK + Orange + Light Magenta + Light Cyan, plus gloss and matte. A complementary platform with a distinct color and finish profile.</p></div></div><p style="font-size:12px">Both presses are owned and operated by Lagersmith LLC, Aluminate's contracted production partner.</p></section>'''+cta)
write('capabilities','Printing Capabilities','''<section class="subhero"><span class="eyebrow">THE ALUMINATE ADVANTAGE</span><h1>Imagination meets <em style="color:#83c9ff;font-style:normal">execution.</em></h1><p>Our production partnership gives your brand access to complementary digital printing platforms, advanced color capabilities and purposeful finishing techniques.</p></section><section class="section"><div class="grid2"><div><span class="eyebrow">COLOR & PRECISION</span><h2>More ways to make an impression.</h2><p>Hinterkopf D360.4: CMYK + Orange with two varnishing stations dedicated to matte and gloss. Velox: CMYK + Orange + Light Magenta + Light Cyan with gloss and matte options.</p><p>These systems offer different strengths. Our team can help match the right production approach to your design objectives.</p></div><img class="photo" src="hero.jpg" alt="Concept printed can designs"></div></section><section class="section light"><span class="eyebrow" style="color:#35729a">PERFORMANCE MATTERS</span><h2>Beautiful. And built to last.</h2><div class="grid3"><div class="feature"><h3>PlasmaMax™</h3><p>Ink adhesion is a central part of our process and product story. Specific test results and standards will be published after validation.</p></div><div class="feature"><h3>Durability</h3><p>Print quality has to stand up to real beverage handling and distribution—not just look great in a rendering.</p></div><div class="feature"><h3>Expert prepress</h3><p>Artwork guidance helps translate a creative vision into a production-ready result.</p></div></div></section><section class="section"><span class="eyebrow">PRODUCTION PARTNERSHIP</span><h2>Specialists behind the finish.</h2><p>Aluminate supplies the printed cans and manages the customer relationship. Lagersmith LLC owns and operates the printing equipment and provides contracted production services.</p><div class="note">Equipment configurations are supplied by Aluminate leadership. Any comparative claims, durability specifications or measured color coverage should be independently validated before public launch.</div></section>'''+cta)
write('finishes','Surface Effects','''<section class="subhero"><span class="eyebrow">ALUMINATE SURFACE EFFECTS™ / WORKING NAME</span><h1>Make the finish <em style="color:#83c9ff;font-style:normal">part of the art.</em></h1><p>Color gets attention. Surface contrast keeps it. Explore the interplay of dedicated matte, brilliant gloss and elevated embellishment.</p></section><section class="section"><div class="grid2"><img class="photo" src="detail.jpg" alt="Concept can showing surface finish contrast"><div><span class="eyebrow">SPOT MATTE + SPOT GLOSS</span><h2>Contrast you can see.</h2><p>With separate matte and gloss varnishing stations on the Hinterkopf D360.4, different areas of a single design can carry distinct finishes.</p><p>Use matte to create a quieter foundation and gloss to emphasize lettering, illustrations and key details.</p></div></div></section><section class="section light"><span class="eyebrow" style="color:#35729a">THE FINISH LIBRARY</span><h2>Every detail has a purpose.</h2><div class="grid3"><div><h3>Dedicated matte</h3><p>A controlled, low-sheen visual treatment. <b>SatinMatte™</b> is a proposed name, pending trademark and product validation.</p></div><div><h3>Spot gloss</h3><p>Selective sheen brings attention to the elements that deserve it.</p></div><div><h3>Dimensional effects</h3><p>Embellishment opportunities that add visual and tactile presence; availability depends on design and production validation.</p></div></div></section><section class="section"><h2>Designed to work together.</h2><p>Our printed matte varnish is not currently equivalent to the soft-touch matte film used on some shrink sleeves. We will describe the actual finish accurately rather than imply a texture we cannot yet produce.</p><div class="note">Illustrative finishes only. Physical samples are required to assess actual sheen, texture and suitability.</div></section>'''+cta)
write('masterworks','Masterworks Gallery','''<section class="subhero"><span class="eyebrow">ALUMINATE MASTERWORKS</span><h1>Extraordinary brands.<br><em style="font-style:normal;color:#83c9ff">Real impact.</em></h1><p>A future gallery of standout customer packaging, creative collaborations and innovative surface treatments.</p></section><section class="section"><div class="grid3"><div><img class="cardimg" src="gallery.jpg" alt="Illustrative colorful can designs"><h3>Color without compromise</h3><p>Concept imagery · expressive graphics and vibrant palettes.</p></div><div><img class="cardimg" src="master.jpg" alt="Illustrative floral beverage can artwork"><h3>Art worth holding</h3><p>Concept imagery · illustration and distinctive shelf presence.</p></div><div><img class="cardimg" src="can.jpg" alt="Illustrative scenic beverage can design"><h3>Detail tells the story</h3><p>Concept imagery · fine lines and nuanced composition.</p></div></div><div class="note" style="margin-top:35px">The imagery on this page is conceptual, not a portfolio of verified customer projects. Before launch, replace it with permission-cleared customer photography, approved brand names and real project details.</div></section>'''+cta)
write('about','About Aluminate','''<section class="subhero"><span class="eyebrow">WHO WE ARE</span><h1>For brands that refuse<br>to look <em style="font-style:normal;color:#83c9ff">ordinary.</em></h1><p>Aluminate brings together creative ambition, specialized can decoration and a focused customer experience.</p></section><section class="section"><div class="grid2"><div><span class="eyebrow">OUR PHILOSOPHY</span><h2>Creative mastery.<br>Engineered.</h2><p>We believe packaging should do more than carry a beverage. It should capture attention, communicate a point of view and hold up to the demands of the real world.</p><p>We work with brands to bring artwork to life through thoughtful print technology, surface effects and dependable production execution.</p></div><img class="photo" src="hero.jpg" alt="Conceptual printed beverage cans"></div></section><section class="section light"><span class="eyebrow" style="color:#35729a">HOW WE WORK</span><h2>One clear relationship.<br>Specialized production.</h2><div class="grid3"><div><h3>01 / Aluminate</h3><p>Your can supplier and primary commercial relationship.</p></div><div><h3>02 / Lagersmith</h3><p>Our contracted production partner, owning and operating the digital printing presses.</p></div><div><h3>03 / Your brand</h3><p>Distinctive packaging supported from concept through finished cans.</p></div></div></section>'''+cta)
write('contact','Start a Project','''<section class="subhero"><span class="eyebrow">LET'S CREATE</span><h1>Tell us what you're<br><em style="font-style:normal;color:#83c9ff">imagining.</em></h1><p>Request samples, ask a technical question or tell us about your next can project.</p></section><section class="section"><form id="inquiry" class="form"><label>YOUR NAME<input name="name" required placeholder="Name"></label><label>COMPANY<input name="company" required placeholder="Brand or business"></label><label>EMAIL<input type="email" name="email" required placeholder="you@company.com"></label><label>PHONE<input type="tel" name="phone" placeholder="Optional"></label><label>WHAT CAN WE HELP WITH?<select name="interest"><option>Request samples</option><option>Get a quote</option><option>Discuss finishes</option><option>Artwork and prepress</option><option>General question</option></select></label><label>CAN FORMAT / QUANTITY<input name="format_quantity" placeholder="e.g., 12oz sleek / 50,000"></label><label class="span2">TELL US ABOUT YOUR PROJECT<textarea name="message" placeholder="Share your idea, timeline, or technical questions"></textarea></label><div class="span2"><button class="btn" type="submit">PREPARE EMAIL INQUIRY ↗</button><p id="formStatus" aria-live="polite"></p><p style="font-size:12px">Prototype behavior: this opens a prefilled email using your device's email application. It does not transmit or save form submissions. Connect a verified form backend before launch.</p></div></form></section>''')
